package me.uc.hussein.ultrasclans.command;

import me.uc.hussein.ultrasclans.gui.GuiManager;
import me.uc.hussein.ultrasclans.model.*;
import me.uc.hussein.ultrasclans.service.*;
import me.uc.hussein.ultrasclans.message.Messages;
import net.kyori.adventure.text.minimessage.MiniMessage;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.command.*;
import org.bukkit.entity.Player;

import java.util.*;

public final class ClanCommand implements CommandExecutor, TabCompleter {
    private final ClanService clans; private final EventService events; private final AllianceService alliances; private final SpawnService spawnService; private final GuiManager gui; private final Messages messages; private final InviteService invites; private final RequestService requests; private final BankService bank; private final WarpService warps; private final TeleportService teleports; private final TpaService tpa; private final PromptService prompts; private final PermissionService perms; private final TaskService tasks;
    public ClanCommand(ClanService c,EventService ev,AllianceService al,SpawnService sp,GuiManager g,Messages m,InviteService i,RequestService r,BankService b,WarpService w,TeleportService tp,TpaService t,PromptService p,PermissionService ps,TaskService ts){clans=c;events=ev;alliances=al;spawnService=sp;gui=g;messages=m;invites=i;requests=r;bank=b;warps=w;teleports=tp;tpa=t;prompts=p;perms=ps;tasks=ts;}
    @Override public boolean onCommand(CommandSender s,Command cmd,String label,String[] a){if(!(s instanceof Player p)){messages.send(s,"player-only");return true;}if(a.length==0){gui.openRoot(p);return true;}String sub=a[0].toLowerCase(Locale.ROOT);Clan c=clans.of(p.getUniqueId());
        switch(sub){
            case "create" -> {if(c!=null){messages.send(p,"already-clan");return true;}p.closeInventory();prompts.set(p.getUniqueId(),new PromptService.Prompt(PromptService.Type.CREATE_CLAN,null,false));messages.send(p,"name-prompt");}
            case "info" -> {if(c==null){messages.send(p,"no-clan");return true;}gui.openClanInfo(p,c);}
            case "members" -> {if(c==null){messages.send(p,"no-clan");return true;}gui.openMembers(p,c);}
            case "invite" -> {if(c==null){messages.send(p,"no-clan");return true;}if(!perms.has(p,c,"CLAN_INVITE")){messages.send(p,"no-permission");return true;}if(a.length<2){prompts.set(p.getUniqueId(),new PromptService.Prompt(PromptService.Type.INVITE_PLAYER,c.id(),false));p.sendMessage(MiniMessage.miniMessage().deserialize("<yellow>Type a player name or cancel.</yellow>"));return true;}Player target=Bukkit.getPlayerExact(a[1]);if(target==null){messages.send(p,"no-player");return true;}invites.invite(c,p,target).thenAccept(ok->Bukkit.getScheduler().runTask(Bukkit.getPluginManager().getPlugin("Ultras_clans"),()->{if(ok){messages.send(p,"invited",Map.of("player",target.getName(),"clan",c.name()));messages.send(target,"invite-received",Map.of("clan",c.name()));}else messages.send(p,"operation-failed");}));}
            case "invites" -> invites.list(p.getUniqueId()).thenAccept(list->Bukkit.getScheduler().runTask(Bukkit.getPluginManager().getPlugin("Ultras_clans"),()->{if(list.isEmpty()){p.sendMessage(MiniMessage.miniMessage().deserialize("<gray>No pending invitations.</gray>"));return;}p.sendMessage(MiniMessage.miniMessage().deserialize("<gold>Pending clan invitations:</gold>"));for(Invitation i:list){Clan x=clans.byId(i.clanId());if(x!=null)p.sendMessage(MiniMessage.miniMessage().deserialize("<white>"+x.name()+"</white> <gray>id="+i.id()+"</gray> <yellow>/clan accept "+i.id()+"</yellow>"));}}));
            case "accept" -> acceptInvite(p,a);
            case "deny" -> denyInvite(p,a);
            case "request" -> {if(c==null){messages.send(p,"no-clan");return true;}messages.send(p,"unknown-command");}
            case "requests" -> requestCommand(p,c,a);
            case "leave" -> {if(c==null){messages.send(p,"no-clan");return true;}if(c.owner().equals(p.getUniqueId())){if(a.length<2||!a[1].equalsIgnoreCase("confirm")){p.sendMessage(MiniMessage.miniMessage().deserialize("<red>Owner leave dissolves the clan.</red> <yellow>Use /clan leave confirm</yellow>"));return true;}Bukkit.getScheduler().runTaskAsynchronously(Bukkit.getPluginManager().getPlugin("Ultras_clans"),()->{});for(UUID id:c.members().keySet()){Player m=Bukkit.getPlayer(id);if(m!=null)messages.send(m,"left",Map.of("clan",c.name()));}String old=c.name();clansDelete(c);p.sendMessage(MiniMessage.miniMessage().deserialize("<red>Clan "+old+" was dissolved.</red>"));}else clans.leave(c,p.getUniqueId()).thenAccept(ok->Bukkit.getScheduler().runTask(Bukkit.getPluginManager().getPlugin("Ultras_clans"),()->messages.send(p,ok?"left":"operation-failed",Map.of("clan",c.name()))));}
            case "kick" -> {if(c==null||a.length<2){messages.send(p,"no-clan");return true;}if(!perms.has(p,c,"CLAN_KICK")){messages.send(p,"no-permission");return true;}Player target=Bukkit.getPlayerExact(a[1]);if(target==null||!c.hasMember(target.getUniqueId())){messages.send(p,"no-player");return true;}clans.kick(c,target.getUniqueId()).thenAccept(ok->Bukkit.getScheduler().runTask(Bukkit.getPluginManager().getPlugin("Ultras_clans"),()->{if(ok)messages.send(target,"kicked",Map.of("clan",c.name()));}));}
            case "promote","demote" -> rankChange(p,c,a,sub.equals("promote"));
            case "settings" -> {if(c==null){messages.send(p,"no-clan");return true;}gui.openSettings(p,c);}
            case "stats" -> {if(c==null){messages.send(p,"no-clan");return true;}gui.openMyClan(p,c);}
            case "top" -> gui.openTop(p);
            case "bank" -> bankCommand(p,c,a);
            case "storage" -> {if(c==null){messages.send(p,"no-clan");return true;}gui.openMyClan(p,c);}
            case "warps","warp" -> warpCommand(p,c,a);
            case "setspawn" -> {if(c==null||!perms.has(p,c,"CLAN_SPAWN_SET")){messages.send(p,"no-permission");return true;}spawnService.set(c.id(),p.getLocation());p.sendMessage(MiniMessage.miniMessage().deserialize("<green>Clan spawn set.</green>"));}
            case "spawn" -> {if(c==null){messages.send(p,"no-clan");return true;}LocationData d=spawnService.get(c.id());if(d==null){p.sendMessage(MiniMessage.miniMessage().deserialize("<red>Clan spawn is not set.</red>"));return true;}Location l=Bukkit.getWorld(d.world())==null?null:new Location(Bukkit.getWorld(d.world()),d.x(),d.y(),d.z(),d.yaw(),d.pitch());if(l!=null)teleports.start(p,l,3,true);}
            case "chat" -> chat(p,c,a);
            case "tag" -> {if(c==null){messages.send(p,"no-clan");return true;}ClanMember m=c.member(p.getUniqueId());if(m==null)return true;m.setTagVisible(a.length<2||!a[1].equalsIgnoreCase("off"));clans.save(c);p.sendMessage(MiniMessage.miniMessage().deserialize("<green>Clan tag "+(m.tagVisible()?"enabled":"disabled")+".</green>"));}
            case "tpa" -> tpaCommand(p,c,a);
            case "tpa_accept" -> tpaAccept(p,a);
            case "tasks","quests" -> {if(c==null){messages.send(p,"no-clan");return true;}gui.openTasks(p,c);}
            case "alliance","alliances" -> allianceCommand(p,c,a);
            case "event","events","challenge" -> eventCommand(p,c,a);
            case "help" -> help(p);
            default -> messages.send(p,"unknown-command");
        }return true; }
    private void requestCommand(Player p,Clan c,String[] a){if(c==null){messages.send(p,"no-clan");return;}requests.list(c).thenAccept(list->Bukkit.getScheduler().runTask(Bukkit.getPluginManager().getPlugin("Ultras_clans"),()->{if(a.length>=3&&a[1].equalsIgnoreCase("accept")){try{UUID id=UUID.fromString(a[2]);var r=list.stream().filter(x->x.id().equals(id)).findFirst().orElse(null);if(r!=null)requests.accept(r,p);}catch(Exception ignored){}}else{p.sendMessage(MiniMessage.miniMessage().deserialize("<gold>Join requests: <white>"+list.size()+"</white></gold>"));for(var r:list)p.sendMessage(MiniMessage.miniMessage().deserialize("<gray>"+r.id()+"</gray> <yellow>/clan requests accept "+r.id()+"</yellow>"));}}));}
    private void acceptInvite(Player p,String[] a){invites.list(p.getUniqueId()).thenAccept(list->{Invitation chosen=null;if(a.length>1)try{UUID id=UUID.fromString(a[1]);for(Invitation i:list)if(i.id().equals(id))chosen=i;}catch(Exception ignored){}if(chosen==null&&!list.isEmpty())chosen=list.get(0);Invitation i=chosen;if(i==null){p.sendMessage(MiniMessage.miniMessage().deserialize("<red>No invitation.</red>"));return;}invites.accept(i,p).thenAccept(ok->Bukkit.getScheduler().runTask(Bukkit.getPluginManager().getPlugin("Ultras_clans"),()->messages.send(p,ok?"joined":"operation-failed",Map.of("clan",Optional.ofNullable(clans.byId(i.clanId())).map(Clan::name).orElse("unknown")))));});}
    private void denyInvite(Player p,String[] a){invites.list(p.getUniqueId()).thenAccept(list->{if(list.isEmpty())return;Invitation i=list.get(0);if(a.length>1)try{UUID id=UUID.fromString(a[1]);i=list.stream().filter(x->x.id().equals(id)).findFirst().orElse(i);}catch(Exception ignored){}invites.remove(i.id());p.sendMessage(MiniMessage.miniMessage().deserialize("<yellow>Invitation denied.</yellow>"));});}
    private void rankChange(Player p,Clan c,String[] a,boolean promote){if(c==null||a.length<2||!perms.has(p,c,promote?"CLAN_PROMOTE":"CLAN_DEMOTE")){messages.send(p,"no-permission");return;}Player target=Bukkit.getPlayerExact(a[1]);if(target==null||!c.hasMember(target.getUniqueId())||target.getUniqueId().equals(c.owner()))return;String[] order={"recruit","member","veteran","officer","general","coleader"};ClanMember m=c.member(target.getUniqueId());int idx=Arrays.asList(order).indexOf(m.rank());int next=promote?Math.min(order.length-1,idx+1):Math.max(0,idx-1);if(idx<0)return;m.setRank(order[next]);clans.save(c);p.sendMessage(MiniMessage.miniMessage().deserialize("<green>Rank updated.</green>"));}
    private void bankCommand(Player p,Clan c,String[] a){if(c==null){messages.send(p,"no-clan");return;}if(a.length==1){gui.openBank(p,c);return;}if(a.length<3){p.sendMessage(MiniMessage.miniMessage().deserialize("<yellow>/clan bank deposit|withdraw <amount></yellow>"));return;}double amount;try{amount=Double.parseDouble(a[2]);}catch(Exception e){return;}boolean ok=a[1].equalsIgnoreCase("deposit")?bank.deposit(p,c,amount):a[1].equalsIgnoreCase("withdraw")&&bank.withdraw(p,c,amount);messages.send(p,ok?(a[1].equalsIgnoreCase("deposit")?"deposit":"withdraw"):"operation-failed",Map.of("amount",String.valueOf(amount)));}
    private void warpCommand(Player p,Clan c,String[] a){if(c==null){messages.send(p,"no-clan");return;}if(a.length==1){gui.openMyClan(p,c);return;}if(a[1].equalsIgnoreCase("create")){if(!perms.has(p,c,"CLAN_WARP_CREATE")){messages.send(p,"no-permission");return;}warps.save(c.id(),p.getLocation()).thenAccept(ok->p.sendMessage(MiniMessage.miniMessage().deserialize(ok?"<green>Warp created.</green>":"<red>Warp limit reached.</red>")));return;}try{int id=Integer.parseInt(a[1]);warps.load(c.id());var list=warps.list(c.id());var w=list.stream().filter(x->x.id()==id).findFirst().orElse(null);if(w==null){p.sendMessage(MiniMessage.miniMessage().deserialize("<red>Warp not found.</red>"));return;}Location l=warps.resolve(w);if(l!=null)teleports.start(p,l,5,true);}catch(NumberFormatException ignored){}}
    private void chat(Player p,Clan c,String[] a){if(c==null){messages.send(p,"no-clan");return;}ClanMember m=c.member(p.getUniqueId());if(m==null||m.muted()){p.sendMessage(MiniMessage.miniMessage().deserialize("<red>You cannot use clan chat.</red>"));return;}m.setChatEnabled(a.length<2||!a[1].equalsIgnoreCase("off"));clans.save(c);p.sendMessage(MiniMessage.miniMessage().deserialize("<green>Clan chat "+(m.chatEnabled()?"enabled":"disabled")+".</green>"));}
    private void tpaCommand(Player p,Clan c,String[] a){if(c==null){messages.send(p,"no-clan");return;}if(a.length<2){p.sendMessage(MiniMessage.miniMessage().deserialize("<yellow>/clan tpa <player></yellow>"));return;}Player target=Bukkit.getPlayerExact(a[1]);if(target==null||!c.hasMember(target.getUniqueId())){messages.send(p,"no-player");return;}boolean ok=tpa.send(p,target,false,60_000,30_000);p.sendMessage(MiniMessage.miniMessage().deserialize(ok?"<green>ᴛᴘᴀ ʀᴇǫᴜᴇsᴛ sᴇɴᴛ</green>":"<red>TPA is on cooldown.</red>"));if(ok)target.sendMessage(MiniMessage.miniMessage().deserialize("<gradient:#ff3333:#8b0000>ULTRAS |</gradient> <white>ᴛᴘᴀ ʀᴇǫᴜᴇsᴛ</white> <gray>from</gray> <white>"+p.getName()+"</white> <gray>Use /clan tpa_accept</gray>"));}
    private void tpaAccept(Player p,String[] a){var r=tpa.get(p.getUniqueId());if(r==null){p.sendMessage(MiniMessage.miniMessage().deserialize("<red>No valid TPA request.</red>"));return;}Player from=Bukkit.getPlayer(r.from());if(from==null){tpa.remove(p.getUniqueId());return;}Location target=r.here()?p.getLocation():p.getLocation();teleports.start(from,target,3,true);tpa.remove(p.getUniqueId());}
    private void allianceCommand(Player p,Clan c,String[] a){if(c==null){messages.send(p,"no-clan");return;}if(a.length<2){gui.openMyClan(p,c);return;}if(a[1].equalsIgnoreCase("add")&&a.length>=3){Clan target=clans.byName(a[2]);if(target!=null&&alliances.request(c,target))p.sendMessage(MiniMessage.miniMessage().deserialize("<green>Alliance request sent.</green>"));else p.sendMessage(MiniMessage.miniMessage().deserialize("<red>Alliance request could not be created.</red>"));}else if(a[1].equalsIgnoreCase("accept")&&a.length>=3){Clan target=clans.byName(a[2]);if(target!=null&&alliances.accept(c,target))p.sendMessage(MiniMessage.miniMessage().deserialize("<green>Alliance established.</green>"));}else if(a[1].equalsIgnoreCase("remove")&&a.length>=3){Clan target=clans.byName(a[2]);if(target!=null)alliances.remove(c,target);}}
    private void eventCommand(Player p,Clan c,String[] a){if(c==null){messages.send(p,"no-clan");return;}if(a.length>=2&&a[1].equalsIgnoreCase("leave")){events.leave(p);p.sendMessage(MiniMessage.miniMessage().deserialize("<yellow>You left the event.</yellow>"));return;}if(a.length>=2&&a[1].equalsIgnoreCase("accept")){if(a.length<3)return;try{ClanEvent e=events.events().stream().filter(x->x.id.toString().equals(a[2])).findFirst().orElse(null);if(e!=null&&e.clanB.equals(c.id()))events.accept(e);}catch(Exception ignored){}return;}if(a.length>=2){if(!perms.has(p,c,"CLAN_EVENT_CREATE")){messages.send(p,"no-permission");return;}Clan target=clans.byName(a[1]);if(target==null||target.id().equals(c.id())){messages.send(p,"not-found");return;}double money=a.length>=3?Double.parseDouble(a[2]):0;long cp=a.length>=4?Long.parseLong(a[3]):0;int minutes=a.length>=5?Integer.parseInt(a[4]):5;int rounds=a.length>=6?Integer.parseInt(a[5]):3;ClanEvent e=events.create(c,target,money,cp,minutes,rounds);if(e==null){messages.send(p,"operation-failed");return;}p.sendMessage(messages.component("challenge-sent",Map.of("clan",target.name())));Player owner=Bukkit.getPlayer(target.owner());if(owner!=null)owner.sendMessage(messages.component("challenge-received",Map.of("clan",c.name())));return;}p.sendMessage(MiniMessage.miniMessage().deserialize("<yellow>/clan challenge <clan> [money] [cp] [minutes] [rounds]</yellow>"));}
    private void help(Player p){p.sendMessage(MiniMessage.miniMessage().deserialize("<gradient:#ff3333:#8b0000>ULTRAS CLANS</gradient> <gray>/clan /clans /clan invite /clan bank /clan storage /clan warp /clan spawn /clan tpa /clan chat /clan tasks /clan top</gray>"));}
    private void clansDelete(Clan c){clans.delete(c);}
    @Override public List<String> onTabComplete(CommandSender s,Command cmd,String label,String[] a){if(!(s instanceof Player p))return List.of();if(a.length==1)return Arrays.asList("create","invite","accept","deny","leave","kick","promote","demote","info","members","invites","settings","stats","top","bank","storage","warp","warps","setspawn","spawn","tpa","tpa_accept","chat","tag","tasks","quests","alliance","alliances","event","events","challenge","help").stream().filter(x->x.startsWith(a[0].toLowerCase())).toList();return List.of();}
}
